<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet">
<title>Operators | A.T.O.M.</title>
<style>
:root{color-scheme:dark;font-family:Inter,ui-sans-serif,system-ui,sans-serif;background:#080d16;color:#e8eef7;--line:#223044;--muted:#8392a8;--muted2:#607087;--lime:#b7f36b;--cyan:#62d9e8;--red:#ff7188}
*{box-sizing:border-box}body{margin:0;min-width:320px;background:radial-gradient(ellipse at 78% -15%,rgba(46,105,130,.2),transparent 38%),#080d16}a{color:inherit;text-decoration:none}.app{min-height:100vh;display:grid;grid-template-columns:252px minmax(0,1fr)}.sidebar{position:sticky;top:0;height:100vh;padding:26px 17px 18px;display:flex;flex-direction:column;background:rgba(10,17,28,.96);border-right:1px solid var(--line)}.brand{display:flex;align-items:center;gap:12px;padding:0 9px 30px}.brand-mark{width:43px;height:43px;display:grid;place-items:center;border-radius:13px;background:linear-gradient(145deg,#d1ff8b,#86c94b);color:#101a20;font-size:20px;font-weight:950}.brand-name{font-size:15px;font-weight:850;letter-spacing:.17em}.brand-caption{margin-top:4px;color:var(--muted2);font-size:9px;letter-spacing:.19em}.side-label{padding:15px 11px 9px;color:#53647a;font-size:9px;font-weight:800;letter-spacing:.18em;text-transform:uppercase}.nav-link,.nav-soon{min-height:43px;display:flex;align-items:center;gap:12px;margin:3px 0;padding:0 12px;border-radius:10px;color:#91a0b5;font-size:12px}.nav-link.active{color:var(--lime);background:rgba(183,243,107,.1);border:1px solid rgba(183,243,107,.12)}.nav-icon{width:19px;text-align:center;font-size:15px}.nav-soon{color:#536176}.soon-tag{margin-left:auto;font-size:8px}.spacer{flex:1}.source{padding:14px;border:1px solid var(--line);border-radius:12px;background:#0d1724;color:var(--muted);font-size:9px}.source strong{display:block;color:var(--lime);margin:8px 0}
.main{min-width:0;padding:30px clamp(18px,3.4vw,48px) 34px}.topbar{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;padding-bottom:24px;border-bottom:1px solid var(--line)}.eyebrow{color:var(--cyan);font-size:9px;font-weight:850;letter-spacing:.2em;text-transform:uppercase}h1{margin:8px 0 5px;font-size:clamp(25px,3vw,34px);letter-spacing:-.055em}.subtitle{color:var(--muted);font-size:11px}.live{padding:9px 13px;border:1px solid rgba(183,243,107,.24);border-radius:8px;background:rgba(183,243,107,.08);color:var(--lime);font-size:9px;font-weight:850;letter-spacing:.13em}
.section-head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:26px 0 13px}.section-head h2{margin:0;font-size:12px}.hint{color:var(--muted2);font-size:9px}.stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.stat,.panel{min-width:0;padding:17px;border:1px solid var(--line);border-radius:13px;background:linear-gradient(145deg,rgba(20,33,49,.98),rgba(13,22,35,.98))}.stat-label{color:#9baabd;font-size:10px}.stat-value{margin-top:12px;color:#f4f7fb;font-size:29px;font-weight:800;letter-spacing:-.055em}.green{color:var(--lime)}.red{color:var(--red)}
.filters{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin-bottom:15px}.field{min-height:39px;padding:0 12px;border:1px solid #2a3b50;border-radius:8px;background:#0b1522;color:#e8eef7;font-size:11px}.search{width:min(360px,100%)}.btn{min-height:39px;display:inline-flex;align-items:center;justify-content:center;padding:0 14px;border:1px solid rgba(183,243,107,.25);border-radius:8px;background:rgba(183,243,107,.1);color:var(--lime);font-size:10px;font-weight:800;cursor:pointer}.btn.secondary{border-color:#2a3b50;background:#142033;color:#aab8ca}
.panel{padding:0;overflow:hidden}.table-wrap{width:100%;overflow-x:auto}table{width:100%;border-collapse:collapse;white-space:nowrap}th{padding:13px 14px;border-bottom:1px solid #2a394d;color:#718198;font-size:8px;font-weight:800;letter-spacing:.12em;text-align:left;text-transform:uppercase}td{padding:14px;border-bottom:1px solid rgba(34,48,68,.68);color:#c8d3e1;font-size:10px}tbody tr:last-child td{border-bottom:0}.name{color:#e5edf7;font-weight:750}.sub{margin-top:4px;color:var(--muted2);font-size:9px}.status{display:inline-block;padding:5px 8px;border:1px solid rgba(183,243,107,.18);border-radius:6px;background:rgba(183,243,107,.08);color:var(--lime);font-size:8px;font-weight:850;text-transform:uppercase}.status.inactive{border-color:rgba(255,113,136,.2);background:rgba(255,113,136,.08);color:var(--red)}.detail-link{color:var(--cyan);font-size:9px;font-weight:750}.empty{padding:28px;color:var(--muted2);text-align:center;font-size:11px}.pagination{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 16px;border-top:1px solid var(--line);color:var(--muted);font-size:9px}.pagination a{padding:8px 11px;border:1px solid #2a3b50;border-radius:7px;color:#dce5f1}.pagination a.disabled{opacity:.35;pointer-events:none}footer{display:flex;justify-content:space-between;gap:12px;margin-top:22px;padding-top:14px;border-top:1px solid rgba(34,48,68,.7);color:#596a80;font-size:8px}
@media(max-width:820px){.app{grid-template-columns:66px minmax(0,1fr)}.sidebar{padding:20px 8px 14px}.brand{justify-content:center;padding:0 0 25px}.brand-copy,.side-label,.nav-text,.soon-tag,.source{display:none}.nav-link,.nav-soon{justify-content:center;padding:0}.main{padding:24px 17px}}@media(max-width:600px){.main{padding:20px 12px 25px}.topbar{flex-direction:column}.stats{grid-template-columns:1fr 1fr;gap:8px}.stat{padding:12px}.stat-value{font-size:25px}.search{width:100%}.filters{align-items:stretch}.filters .field,.filters .btn{flex:1}footer{flex-direction:column}}@media(max-width:360px){.app{grid-template-columns:54px minmax(0,1fr)}.main{padding-left:9px;padding-right:9px}}
