<main class="main"><header class="topbar"><div><div class="eyebrow">Biometric access intelligence / identity</div><h1>Operators</h1><div class="subtitle">Registered fingerprint operators across connected devices.</div></div><div class="live">● OPERATOR DIRECTORY</div></header>
<div class="section-head"><h2>Operator status</h2><span class="hint">Live records · atomic_access</span></div><section class="stats">
<article class="stat"><div class="stat-label">Total operators</div><div class="stat-value">{{ number_format($totalOperators) }}</div></article><article class="stat"><div class="stat-label">Active</div><div class="stat-value green">{{ number_format($activeOperators) }}</div></article><article class="stat"><div class="stat-label">Inactive</div><div class="stat-value red">{{ number_format($inactiveOperators) }}</div></article></section>
<div class="section-head"><h2>Registered operators</h2><span class="hint">{{ $operators->total() }} matching records</span></div><section class="panel">
<form class="filters" method="GET" action="{{ route('operators.index') }}" style="padding:16px 16px 0"><input class="field search" type="search" name="q" value="{{ $filters['q'] ?? '' }}" placeholder="Search operator, ID, device, fingerprint slot..."><select class="field" name="status" aria-label="Filter status"><option value="">All status</option><option value="active" @selected(($filters['status'] ?? '') === 'active')>Active</option><option value="inactive" @selected(($filters['status'] ?? '') === 'inactive')>Inactive</option></select><button class="btn" type="submit">Apply filter</button><a class="btn secondary" href="{{ route('operators.index') }}">Reset</a></form>
